document.documentElement.classList.add("js");
const CV_PDF =
  "";
function cvBlob() {
  const b = atob(CV_PDF),
    a = new Uint8Array(b.length);
  for (let i = 0; i < b.length; i++) a[i] = b.charCodeAt(i);
  return new Blob([a], { type: "application/pdf" });
}
document.querySelectorAll("[data-cv]").forEach((el) =>
  el.addEventListener("click", (e) => {
    if (el.dataset.cvManaged === "true") return;
    e.preventDefault();
    const u = URL.createObjectURL(cvBlob());
    if (el.dataset.cv === "open") {
      window.open(u, "_blank");
    } else {
      const a = document.createElement("a");
      a.href = u;
      a.download = "CV_Angie_Sohane_Ndaghy_Pambo.pdf";
      document.body.appendChild(a);
      a.click();
      a.remove();
    }
    setTimeout(() => URL.revokeObjectURL(u), 60000);
  }),
);
/* curseur (souris uniquement) */
if (matchMedia("(hover:hover)").matches) {
  const c = document.getElementById("cursor"),
    r = document.getElementById("cursor-ring");
  let mx = 0,
    my = 0,
    rx = 0,
    ry = 0;
  addEventListener("mousemove", (e) => {
    mx = e.clientX;
    my = e.clientY;
    c.style.left = mx + "px";
    c.style.top = my + "px";
  });
  (function loop() {
    rx += (mx - rx) * 0.12;
    ry += (my - ry) * 0.12;
    r.style.left = rx + "px";
    r.style.top = ry + "px";
    requestAnimationFrame(loop);
  })();
  document.querySelectorAll("a,button").forEach((el) => {
    el.addEventListener("mouseenter", () => {
      c.style.width = c.style.height = "20px";
      r.style.width = r.style.height = "52px";
      r.style.opacity = ".4";
    });
    el.addEventListener("mouseleave", () => {
      c.style.width = c.style.height = "12px";
      r.style.width = r.style.height = "36px";
      r.style.opacity = ".6";
    });
  });
}
/* apparition au scroll */
const rv = document.querySelectorAll(".reveal");
if ("IntersectionObserver" in window) {
  const io = new IntersectionObserver(
    (es) =>
      es.forEach((x) => {
        if (x.isIntersecting) {
          x.target.classList.add("visible");
          io.unobserve(x.target);
        }
      }),
    { threshold: 0.1 },
  );
  rv.forEach((el) => io.observe(el));
} else rv.forEach((el) => el.classList.add("visible"));
document
  .querySelectorAll(
    ".skills-grid,.projects-grid,.cert-grid,.qualities-list,.interests-grid,.works-grid,.tool-row,.stats",
  )
  .forEach((g) => {
    g.querySelectorAll(".reveal,.tool-card").forEach((ch, i) => {
      ch.style.transitionDelay = i * 0.07 + "s";
    });
  });
/* menu mobile */
const nt = document.getElementById("navToggle"),
  nl = document.getElementById("navLinks");
nt.addEventListener("click", () => {
  const o = nl.classList.toggle("open");
  nt.setAttribute("aria-expanded", o);
});
nl.querySelectorAll("a").forEach((a) =>
  a.addEventListener("click", () => {
    nl.classList.remove("open");
    nt.setAttribute("aria-expanded", "false");
  }),
);
/* lien actif + bouton haut de page */
const secs = document.querySelectorAll("section[id]"),
  links = document.querySelectorAll(".nav-links a"),
  tt = document.getElementById("toTop");
addEventListener(
  "scroll",
  () => {
    let cur = "";
    secs.forEach((s) => {
      if (scrollY >= s.offsetTop - 160) cur = s.id;
    });
    links.forEach((a) => {
      a.style.color =
        a.getAttribute("href") === "#" + cur ? "var(--white)" : "";
    });
    tt.classList.toggle("show", scrollY > 700);
  },
  { passive: true },
);
tt.addEventListener("click", () => scrollTo({ top: 0, behavior: "smooth" }));
/* galerie : filtres + lightbox */
document.querySelectorAll(".work-filter").forEach((b) =>
  b.addEventListener("click", () => {
    document
      .querySelectorAll(".work-filter")
      .forEach((x) => x.classList.remove("active"));
    b.classList.add("active");
    const f = b.dataset.filter;
    document
      .querySelectorAll(".work-card")
      .forEach((c) =>
        c.classList.toggle("hide", f !== "all" && c.dataset.cat !== f),
      );
  }),
);
const lb = document.getElementById("lightbox"),
  lbi = lb.querySelector("img");
document.querySelectorAll(".projects-grid,.works-grid").forEach((gallery) =>
  gallery.addEventListener("click", (event) => {
    const im = event.target.closest("img[data-gallery-image]");
    if (!im) return;
    lbi.src = im.currentSrc || im.src;
    lbi.alt = im.alt;
    lb.classList.add("open");
  }),
);
lb.addEventListener("click", (e) => {
  if (e.target !== lbi) lb.classList.remove("open");
});
addEventListener("keydown", (e) => {
  if (e.key === "Escape") lb.classList.remove("open");
});
/* formulaire : ouvre la messagerie avec le message prêt */
function handleSubmit(e) {
  e.preventDefault();
  const g = (id) => document.getElementById(id).value.trim();
  const subj = g("subject") || "Prise de contact depuis le portfolio";
  const body =
    g("message") +
    "\n\n— " +
    g("fname") +
    " " +
    g("lname") +
    " (" +
    g("email") +
    ")";
  const contactEmail =
    document.querySelector('[data-cms="contact_email"]')?.textContent.trim() ||
    "angiesohane@gmail.com";
  location.href =
    `mailto:${contactEmail}?subject=` +
    encodeURIComponent(subj) +
    "&body=" +
    encodeURIComponent(body);
  const s = document.getElementById("formSuccess");
  s.style.display = "block";
  setTimeout(() => {
    s.style.display = "none";
  }, 7000);
}
document
  .querySelector(".contact-form")
  .addEventListener("submit", handleSubmit);
